def predict(probe):
    # Beliefs:
    # Outside the special interval, output = floor(x)+1 if x>0 else floor(x)-1 [E2,E3,E4,E5,E6,E10,E16]
    #   (0.0 -> -1, negatives get an extra -1, positives an extra +1) [E4,E10]
    # There is a "noisy" region roughly x in [33.4, 42.0] where output is a small
    #   negative number instead of the step function [E16,E18,E20,E22,E24]
    #   Left boundary between 33.3 and 33.4 [E22,E24]; right boundary between
    #   42.01 and 42.05 (treat as 42.0) [E16,E20,E22].
    # Inside the region the values look like noise in about [-0.9,-0.2];
    #   no reproducible pattern is visible, so return the mean-ish -0.45 [?]
    import math
    xs = probe.get("x", [])
    ys = []
    for x in xs:
        if x is None:
            ys.append(None)
            continue
        if 33.4 <= x <= 42.0:
            ys.append(-0.45)  # noisy region; best guess at central value
        else:
            if x > 0:
                ys.append(float(math.floor(x) + 1))
            else:
                ys.append(float(math.floor(x) - 1))
    return {"y": ys}
